 var ranges;
 let seed = Math.random() * 7692;
 var mySize, margin, grad;
 let str_wei = 0;

 // colors
 let colorsbg = "4982A6-010626-4D4C73".split("-").map((a) => "#" + a);
 // colors of rainbow: red orange yellow green blue purple
 let colors1 = "F24C3D-F2490C-F2D64B-9DD962-73D9D9-6CAFD9-A85FD9".split("-").map((a) => "#" + a);

 let color1, color2;
 let colorselet = [];

 let unit_x, unit_y;
 let count;
 let mods = [];
 let stop_count = 0;

 function setup() {
 	// pixelDensity(5);
 	randomSeed(seed);
 	mySize = max(windowWidth, windowHeight);
 	margin = mySize / 100;
 	createCanvas(1112, 834);
 	colorselet[0] = random(colors1);
 	colorselet[1] = random(colors1);
 	colorselet[2] = random(colors1);
 	colorselet[4] = random(colors1);
 	unit_x = width;
 	unit_y = unit_x / 16 * 11;

 	noStroke();
 	let plusNum = int(random(10, 20));
 	let wideCount = width / unit_x;
 	let highCount = height / unit_y + plusNum;
 	count = wideCount * highCount;

 	let index = 0;
 	for (let y = 0; y < highCount; y++) {
 		for (let x = 0; x < wideCount; x++) {
 			mods[index++] = new Module(
 				x * unit_x - unit_x / 100,
 				y * unit_y / (plusNum + 1),
 				0,
 				0,
 				random(0.5, 1.0),
 				1 * unit_x
 			);
 		}
 	}
 	let filter1 = new makeFilter();
 	background(random(colorsbg));
 }

 function draw() {
 	randomSeed(seed);
 	blendMode(SCREEN);

 	for (let i = 0; i < count; i++) {
 		mods[i].update();
 		mods[i].draw();
 		if (stop_count == 1) {
 			blendMode(BLEND);
 			image(overAllTexture, 0, 0);
 			noFill();
 			stroke("#202020");
 			strokeWeight(margin);
 			rectMode(CORNER);
 			//rect(0, 0, width, height);
 			noLoop();
 		}
 	}
 }

 class Module {
 	constructor(xOff, yOff, x, y, speed, unit) {
 		this.xOff = xOff;
 		this.yOff = yOff;
 		this.x = x;
 		this.y = y;
 		this.speed = speed * 2;
 		this.unit = unit;
 		this.xDir = 1;
 		this.yDir = 1 / 16 * 11;
 	}

 	// Custom method for updating the variables
 	update() {
 		this.x = this.x + this.speed * this.xDir;
 		this.y = this.y + this.speed * this.yDir / 10;
 		if (this.x >= this.unit * 2 || this.x <= 0) {
 			this.xDir *= -1;
 			stop_count++;
 			this.x = this.x + 1 * this.xDir;
 			this.y = this.y + 1 * this.yDir;
 		}
 		if (this.y >= this.unit || this.y <= 0) {
 			this.yDir *= -1 / 16 * 11;
 			this.y = this.y + 1 * this.yDir;
 		}
 	}

 	// Custom method for drawing the object
 	draw() {
 		stroke(str(colorselet[1]) + "1a");
 		strokeWeight(0.01);
 		fill(str(random(colorselet)) + "80");

 		//shadow & highlight
 		drawingContext.shadowColor = "#ffffff33";
 		drawingContext.shadowOffsetX = -1;
 		drawingContext.shadowOffsetY = -1;
 		drawingContext.shadowBlur = 0;
 		drawingContext.shadowColor = "#2f2f2f1a";
 		drawingContext.shadowOffsetX = 1;
 		drawingContext.shadowOffsetY = 1;
 		drawingContext.shadowBlur = 0;

 		//shape 
 		let y_size = 0;
 		if (int(seed) % 3 == 1) {
 			y_size = this.unit * cos(random(0.75, 0.35) * frameCount * 0.01) / 3;
 		}else if (int(seed) % 3 == 2) {
 			y_size = this.unit * sin(random(0.75, 0.35) * frameCount * 0.01) / 3;
 		}else {
 			y_size = this.unit * tan(random(0.75, 0.35) * frameCount * 0.01) / 3;
 		}
 		let rio = random(0.5, 0.2);
 		let y_plus = y_size * rio;
 		push();
 		translate(this.xOff + this.x - mySize / 10, this.yOff + this.y);

 		//gradient
 		grad = drawingContext.createLinearGradient(0, y_plus - y_size / 16 * 7 / 2, 0, y_plus + y_size / 16 * 7 / 2);
 		grad.addColorStop(0, str(random(colorsbg)) + "00");
 		grad.addColorStop(0.5 + random(-0.45, 0.45), random(colors1));
 		grad.addColorStop(1, str(random(colors1)) + "00");
 		drawingContext.fillStyle = grad;
 		rectMode(CENTER);
 		rect(-y_size / 32 * 2, y_plus, (y_size / 16 * 3 - y_plus) * 0.05, y_size / 16 * 7);
 		pop();
 	}
 }

 function makeFilter() {
 	// make noise filter
 	colorMode(HSB, 360, 100, 100, 100);
 	drawingContext.shadowColor = color(0, 0, 5, 95);
 	overAllTexture = createGraphics(windowWidth, windowHeight);
 	overAllTexture.loadPixels();
 	for (var i = 0; i < width; i++) { // noprotect
 		for (var j = 0; j < height; j++) {
 			overAllTexture.set(
 				i,
 				j,
 				color(
 					0,
 					0,
 					99,
 					noise(i / 3, j / 3, (i * j) / 50) * random(5, 15) / 2
 				)
 			);
 		}
 	}
 	overAllTexture.updatePixels();
 }

 // save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

